mapper.select:
SELECT a.`transport_way` `transportWay`, b.`area_name` `areaName`, a.`device_id` `deviceId`, b.`genre_name` `deviceType`, a.`run_time` `runTime`, a.`floor` `floor`, a.`area_id` `areaId`, b.`device_name` `deviceName` FROM `lift_record` a LEFT JOIN `security_device` b ON a.`device_id` = b.`device_id` where b.`application_code` = 'LIFT_MANAGEMENT'
and a.`create_time` >= #{param.period.begin}
and a.`create_time` <= #{param.period.end}
and a.`transport_way` = #{param.transportWay}
and b.`device_name` like concat('%',#{param.keyword},'%')
and b.`area_id` like concat('%',#{param.area},'%')

SELECT COALESCE( count (`id`), 0 ) `dataValue`, DATE_FORMAT( a.`run_time`, ${dateFormat} ) `timeFlag` FROM `lift_record` a
and a.`run_time` >= #{st}
and a.`run_time` <= #{et}
GROUP BY DATE_FORMAT( a.`run_time`, ${dateFormat})

SELECT COALESCE( count (`id`), 0 ) `dataValue`, DATE_FORMAT( a.`run_time`, ${dateFormat} ) `timeFlag` FROM `lift_record` a
and a.`run_time` >= #{st}
and a.`run_time` <= #{et}
GROUP BY DATE_FORMAT( a.`run_time`, ${dateFormat})

SELECT COALESCE( count(`id`), 0 ) `dataValue`, to_char( a.`run_time`, ${dateFormat} ) `timeFlag` FROM `lift_record` a
and a.`run_time` >= #{st}
and a.`run_time` <= #{et}
GROUP BY to_char( a.`run_time`, ${dateFormat})
